-- Formazione, obiettivi e metriche della corsa p20261010010521tjb applicati a RTL (voce 4 del coordinatore, 2026-11-11). GENERATO da genera_R_corsa.py.
-- Moduli formativi del tenant, modelli di obiettivo per ruolo (solo ruoli con un posto RTL abbinato), indicatori con definizione di metrica e traguardi per posto.
-- Idempotente (codici e chiavi naturali). Giornale: staging.rtl_allinea_org_undo (righe inserite come 'ins:<tabella>').
\set ON_ERROR_STOP on
BEGIN;
CREATE TABLE IF NOT EXISTS staging.rtl_allinea_org_undo (salvato_il timestamptz NOT NULL DEFAULT now(), tabella text NOT NULL, chiave uuid NOT NULL, riga jsonb NOT NULL, PRIMARY KEY (tabella, chiave));
CREATE TEMP TABLE rap ON COMMIT DROP AS SELECT DISTINCT ON (pc.codice) pc.codice, a.user_position_assignment_position_id pos, p.position_job_role_id ruolo
FROM staging.rtl_persona_corsa pc JOIN sys.sys_users u ON u.user_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0' AND u.user_last_name||', '||u.user_first_name=pc.persona
JOIN sys.sys_user_position_assignments a ON a.user_position_assignment_user_id=u.user_id AND a.user_position_assignment_status='ACTIVE' AND a.user_position_assignment_kind='PRIMARY'
JOIN sys.sys_positions p ON p.position_id=a.user_position_assignment_position_id ORDER BY pc.codice, a.user_position_assignment_position_id;
