CREATE TEMP TABLE ob(ruolo_corsa text, id text, testo text, tipo text, orizzonte text, peso numeric) ON COMMIT DROP;
SELECT gen_random_uuid(), '86ba7a65-217f-48ba-8ce5-5c09b40a66b0', r.ruolo, 'GOAL_TEMPLATE::86ba7a65-217f-48ba-8ce5-5c09b40a66b0::TJB::'||o.ruolo_corsa||'::'||o.id, left(o.testo,250), o.testo,
  CASE o.tipo WHEN 'CONFORMITA' THEN 'conformità' WHEN 'COSTO' THEN 'costi' WHEN 'CRESCITA' THEN 'crescita' WHEN 'EFFICIENZA' THEN 'efficienza' WHEN 'QUALITA' THEN 'qualità' WHEN 'SERVIZIO' THEN 'servizio' ELSE NULL END, 'OBJECTIVE', 365, o.peso, CASE o.tipo WHEN 'CRESCITA' THEN 'STRETCH' WHEN 'COSTO' THEN 'HARD' WHEN 'CONFORMITA' THEN 'MEDIUM' WHEN 'EFFICIENZA' THEN 'MEDIUM' WHEN 'QUALITA' THEN 'MEDIUM' WHEN 'SERVIZIO' THEN 'MEDIUM' ELSE 'MEDIUM' END, false, true, jsonb_build_object('corsa','p20261010010521tjb','ruolo_corsa',o.ruolo_corsa,'obiettivo',o.id,'allinea','R')
FROM ob o JOIN rap r ON r.codice=o.ruolo_corsa WHERE NOT EXISTS (SELECT 1 FROM sys.sys_goal_templates g WHERE g.template_natural_key='GOAL_TEMPLATE::86ba7a65-217f-48ba-8ce5-5c09b40a66b0::TJB::'||o.ruolo_corsa||'::'||o.id);
CREATE TEMP TABLE mt(id text, nome text, unita text, formula text, direzione text, obiettivo text) ON COMMIT DROP;
SELECT gen_random_uuid(), '86ba7a65-217f-48ba-8ce5-5c09b40a66b0', 'TJB-'||m.id, left(m.nome,250), m.nome, m.formula, m.unita, CASE m.direzione WHEN 'AUMENTARE' THEN 'HIGHER_IS_BETTER' WHEN 'RIDURRE' THEN 'LOWER_IS_BETTER' WHEN 'MANTENERE' THEN 'TARGET_RANGE' ELSE 'TARGET_RANGE' END, false, jsonb_build_object('corsa','p20261010010521tjb','obiettivo',m.obiettivo,'allinea','R')
FROM mt m WHERE NOT EXISTS (SELECT 1 FROM sys.sys_kpi_definitions k WHERE k.kpi_definition_code='TJB-'||m.id AND k.kpi_definition_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0');
SELECT gen_random_uuid(), k.kpi_definition_id, 'TJB-'||m.id||'-M', left(m.nome,250), m.unita, 'CUSTOM', '{"allinea":"R"}'::jsonb FROM mt m JOIN sys.sys_kpi_definitions k ON k.kpi_definition_code='TJB-'||m.id AND k.kpi_definition_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'
WHERE NOT EXISTS (SELECT 1 FROM sys.sys_kpi_metric_definitions d WHERE d.kpi_metric_definition_code='TJB-'||m.id||'-M');
CREATE TEMP TABLE bs(metrica text, minimo numeric, massimo numeric, obiettivo numeric) ON COMMIT DROP;
SELECT gen_random_uuid(), '86ba7a65-217f-48ba-8ce5-5c09b40a66b0', k.kpi_definition_id, r.pos, DATE '2026-01-01', DATE '2026-12-31', COALESCE(b.obiettivo, (b.minimo+b.massimo)/2, b.minimo, b.massimo), b.minimo, b.massimo, k.kpi_definition_unit, '{"allinea":"R"}'::jsonb
FROM bs b JOIN mt m ON m.id=b.metrica JOIN sys.sys_kpi_definitions k ON k.kpi_definition_code='TJB-'||m.id AND k.kpi_definition_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'
JOIN ob o ON o.id=m.obiettivo JOIN rap r ON r.codice=o.ruolo_corsa
WHERE NOT EXISTS (SELECT 1 FROM sys.sys_kpi_targets t WHERE t.kpi_target_kpi_id=k.kpi_definition_id AND t.kpi_target_position_id=r.pos AND t.kpi_target_period_start=DATE '2026-01-01');
COMMIT;
SELECT 'R ok' esito, (SELECT count(*) FROM sys.sys_learning_modules WHERE learning_module_metadata->>'allinea'='R') moduli, (SELECT count(*) FROM sys.sys_goal_templates WHERE template_metadata->>'allinea'='R') modelli_obiettivo, (SELECT count(*) FROM sys.sys_kpi_definitions WHERE kpi_definition_metadata->>'allinea'='R') indicatori, (SELECT count(*) FROM sys.sys_kpi_targets WHERE kpi_target_metadata->>'allinea'='R') traguardi;
